from math import floor, log, log2
p=[0.25,0.5,0.25]
def depths(q):
    bucket=[floor(log2(log2(1/a))) for a in q]
    d=[]
    for x in range(len(q)):
        z=0
        for y in range(len(q)):
            b=bucket[min(x,y):max(x,y)+1]
            m=min(b)
            if bucket[y]==m: z+=1/b.count(m)
        d.append(z)
    return bucket,d,sum(a*b for a,b in zip(p,d))
print('True probabilities:',p,'buckets, expected depths, mean cost:',depths(p))
for e in [1e-2,1e-4,1e-6]:
    q=[.25+e,.5-e,.25]
    kl=sum(a*log(a/b) for a,b in zip(p,q))
    print('epsilon:',e,'KL:',kl,'buckets, expected depths, mean cost:',depths(q))
